import { PYQQuestion } from "./previousYearPapers";

// ── AEO Model Paper 1 — Based on TGPSC/APPSC AEO Exam Pattern ──────────────
export const AEO_PAPER_1: PYQQuestion[] = [
  // ── AGRICULTURAL EXTENSION (20) ──
  { id:"aeo1_001", year:2017, subject:"extension", question:"The term 'Extension Education' was first used by:", options:["Seaman Knapp","J.P. Leagans","Cambridge University, England","Cornell University, USA"], correct:1, explanation:"J.P. Leagans first used the term 'Extension Education' in a formal academic sense. Extension as a concept was first developed at Cambridge University, but the academic term was defined and popularized by Leagans." },
  { id:"aeo1_002", year:2017, subject:"extension", question:"The 'Etawah Pilot Project' was started in:", options:["1945","1948","1952","1960"], correct:1, explanation:"The Etawah Pilot Project (UP) was started in 1948 under Albert Mayer with US technical assistance. It served as the model for India's Community Development Programme launched in 1952." },
  { id:"aeo1_003", year:2017, subject:"extension", question:"The National Extension Service (NES) was launched in India in:", options:["1952","1953","1956","1960"], correct:1, explanation:"The National Extension Service (NES) was launched in October 1953, one year after the Community Development Programme (CDP, October 1952). NES extended the CDP approach to more villages at lower input levels." },
  { id:"aeo1_004", year:2017, subject:"extension", question:"ATMA stands for:", options:["Agricultural Technology Management Agency","Agricultural Transfer Management Association","Agri-Tech Marketing Agency","Agricultural Training and Management Authority"], correct:0, explanation:"ATMA (Agricultural Technology Management Agency) is a district-level autonomous body established under the National Agricultural Technology Project (NATP) to integrate agricultural extension services at the district level." },
  { id:"aeo1_005", year:2017, subject:"extension", question:"The 'adoption curve' showing cumulative adopters over time is:", options:["Bell-shaped curve","S-shaped (sigmoid) curve","J-shaped curve","U-shaped curve"], correct:1, explanation:"The cumulative adoption curve (when plotted as total adopters over time) forms an S-shaped (sigmoid) curve. The non-cumulative (per year) distribution follows a bell-shaped normal distribution." },
  { id:"aeo1_006", year:2017, subject:"extension", question:"Which of the following is NOT a mass contact method of extension?", options:["Radio","Television","Farm visit","Newspaper"], correct:2, explanation:"Farm visit is an individual contact method (one-to-one contact). Radio, television, and newspapers are mass media methods that reach large audiences simultaneously with one-way communication." },
  { id:"aeo1_007", year:2017, subject:"extension", question:"The 'innovators' in Rogers' adopter categories constitute approximately what percentage of the population?", options:["2.5%","13.5%","34%","16%"], correct:0, explanation:"According to Everett Rogers (Diffusion of Innovations, 1962), the five adopter categories are: Innovators 2.5%, Early Adopters 13.5%, Early Majority 34%, Late Majority 34%, Laggards 16%." },
  { id:"aeo1_008", year:2017, subject:"extension", question:"Which extension approach involves showing farmers how to perform an operation step-by-step?", options:["Result demonstration","Method demonstration","Farm visit","Group meeting"], correct:1, explanation:"Method demonstration shows HOW to perform a skill or practice — the extension worker demonstrates the process step-by-step. Result demonstration shows WHAT results can be achieved by adopting a practice." },
  { id:"aeo1_009", year:2017, subject:"extension", question:"Krishi Vigyan Kendra (KVK) was first established in India at:", options:["Pondicherry in 1974","Ludhiana in 1980","Hyderabad in 1976","Delhi in 1972"], correct:0, explanation:"The first Krishi Vigyan Kendra (KVK) was established in 1974 at Pondicherry (Puducherry) under Tamil Nadu Agricultural University, based on the recommendation of Dr. Mohan Singh Mehta's Education Commission report." },
  { id:"aeo1_010", year:2017, subject:"extension", question:"The primary objective of agricultural extension is:", options:["To increase government revenue","To help farmers help themselves","To distribute subsidies to farmers","To conduct agricultural research"], correct:1, explanation:"The primary objective of agricultural extension is 'to help farmers help themselves' — empowering farmers with knowledge, skills, and motivation to solve their own problems and improve their livelihoods sustainably." },
  { id:"aeo1_011", year:2017, subject:"extension", question:"'Rytu Bharosa' scheme in Telangana provides annual investment support of:", options:["₹4,000 per acre","₹8,000 per acre","₹10,000 per acre","₹6,000 per acre"], correct:1, explanation:"Rythu Bandhu (Rytu Bharosa in some references) provides ₹10,000 per acre per year (₹5,000 per crop, twice yearly) as investment support directly to farmers. As of the latest revision, the amount is ₹10,000/acre/year." },
  { id:"aeo1_012", year:2017, subject:"extension", question:"PM-KISAN scheme provides direct income support of ₹6,000 per year in how many instalments?", options:["Two instalments of ₹3,000","Three instalments of ₹2,000","Four instalments of ₹1,500","Six instalments of ₹1,000"], correct:1, explanation:"PM-KISAN (Pradhan Mantri Kisan Samman Nidhi) provides ₹6,000 per year in three equal instalments of ₹2,000 each (April-July, August-November, December-March) directly to eligible farmers' bank accounts." },
  { id:"aeo1_013", year:2017, subject:"extension", question:"The 'Farmer Field School' (FFS) concept was developed by:", options:["ICAR, India","FAO in Indonesia for IPM training","World Bank","NABARD"], correct:1, explanation:"Farmer Field School (FFS) concept was developed by FAO in Indonesia in 1989 for Integrated Pest Management (IPM) training. It uses experiential, group-based, hands-on learning in the actual field as a 'school without walls'." },
  { id:"aeo1_014", year:2017, subject:"extension", question:"'Soil Health Card' scheme was launched in India in:", options:["2012","2015","2017","2019"], correct:1, explanation:"The Soil Health Card (SHC) scheme was launched by PM Narendra Modi on 19 February 2015 from Suratgarh, Rajasthan. It provides farmers a card containing soil health information and fertilizer recommendations for their land." },
  { id:"aeo1_015", year:2017, subject:"extension", question:"Which of the following is a voluntary organisation working in rural development?", options:["NABARD","Self Help Group (SHG)","State Agriculture Department","ICAR"], correct:1, explanation:"Self Help Groups (SHGs) are voluntary, informal community-based organisations of 10–20 members (usually women) who save regularly and access credit. They are key instruments of rural financial inclusion and women empowerment." },
  { id:"aeo1_016", year:2017, subject:"extension", question:"The Training and Visit (T&V) Extension System was recommended for India by:", options:["ICAR, 1965","World Bank through Daniel Benor","FAO, 1970","Planning Commission, 1980"], correct:1, explanation:"The T&V System was introduced in India in 1974 on the recommendation of World Bank through Daniel Benor. It standardised extension work with regular fortnightly farm visits and monthly training of Village Level Workers (VLWs)." },
  { id:"aeo1_017", year:2017, subject:"extension", question:"'e-NAM' (National Agriculture Market) was launched in:", options:["2013","2014","2016","2018"], correct:2, explanation:"e-NAM (National Agriculture Market) was launched on 14 April 2016 by Prime Minister Modi. It is an online trading portal linking existing APMC (mandi) markets to create a unified national market for agricultural commodities." },
  { id:"aeo1_018", year:2017, subject:"extension", question:"MGNREGA provides guaranteed employment of how many days per year?", options:["100 days","150 days","200 days","50 days"], correct:0, explanation:"MGNREGA (Mahatma Gandhi National Rural Employment Guarantee Act, 2005) guarantees at least 100 days of unskilled manual work per financial year to every rural household whose adult members demand employment." },
  { id:"aeo1_019", year:2017, subject:"extension", question:"The 'Rashtriya Krishi Vikas Yojana' (RKVY) was launched in:", options:["2007-08","2010-11","2012-13","2005-06"], correct:0, explanation:"RKVY (Rashtriya Krishi Vikas Yojana) was launched in 2007-08 as a Centrally Sponsored Scheme to incentivise states to increase public investment in agriculture with flexibility and autonomy. It aims at 4% annual growth in agriculture." },
  { id:"aeo1_020", year:2017, subject:"extension", question:"The component of ATMA that involves farmers visiting progressive farmers and successful demonstrations in other locations is:", options:["Kisan Call Centre","Exposure visit","Farm school","Field day"], correct:1, explanation:"Exposure visits (also called farmer study tours) take farmers to progressive farms, research stations, and successful demonstrations in other regions to motivate adoption through seeing, believing, and learning from success stories." },

  // ── AGRONOMY (20) ──
  { id:"aeo1_021", year:2017, subject:"agronomy", question:"The critical period for crop-weed competition in cotton is:", options:["0–15 DAS","15–60 DAS","60–90 DAS","90–120 DAS"], correct:1, explanation:"The critical period for crop-weed competition in cotton is 15–60 DAS (days after sowing). Weed control during this period is essential to prevent significant yield loss, as cotton is a slow-growing crop in early stages." },
  { id:"aeo1_022", year:2017, subject:"agronomy", question:"Kharif season crops are generally sown during:", options:["October–November","June–July","February–March","December–January"], correct:1, explanation:"Kharif crops are sown at the beginning of the southwest monsoon season, generally in June–July. They are harvested after the monsoon (September–October). Major kharif crops: rice, maize, groundnut, cotton, soybean." },
  { id:"aeo1_023", year:2017, subject:"agronomy", question:"The scientific name of wheat is:", options:["Oryza sativa","Triticum aestivum","Zea mays","Sorghum bicolor"], correct:1, explanation:"Triticum aestivum is the scientific name of bread wheat (common wheat). Oryza sativa is rice, Zea mays is maize, and Sorghum bicolor is sorghum." },
  { id:"aeo1_024", year:2017, subject:"agronomy", question:"Paddy requires how much water for one kg of grain production?", options:["500 litres","1,000 litres","2,000 litres","3,000–5,000 litres"], correct:3, explanation:"Paddy (rice) is a highly water-intensive crop, requiring approximately 3,000–5,000 litres of water per kg of grain produced. This is why water-saving technologies like SRI and AWD are promoted for rice cultivation." },
  { id:"aeo1_025", year:2017, subject:"agronomy", question:"Nitrogen fixation by free-living bacteria in soil — Azotobacter fixes approximately how much N/ha/year?", options:["2–5 kg","10–25 kg","50–100 kg","200 kg"], correct:1, explanation:"Azotobacter, a free-living aerobic nitrogen-fixing bacterium, can fix approximately 10–25 kg N/ha/year under favourable conditions. This is much less than symbiotic fixers (Rhizobium fixes 50–300 kg N/ha/year in legumes)." },
  { id:"aeo1_026", year:2017, subject:"agronomy", question:"The term 'photoperiodism' refers to:", options:["Effect of light intensity on plant growth","Response of plants to the relative length of day and night","Rate of photosynthesis in plants","Light absorption by chlorophyll"], correct:1, explanation:"Photoperiodism is the response of plants to the relative length of day (photoperiod) and night. It controls flowering: short-day plants flower in short days (long nights), long-day plants in long days, and day-neutral plants are unaffected." },
  { id:"aeo1_027", year:2017, subject:"agronomy", question:"Which of the following is a rabi crop?", options:["Cotton","Paddy","Wheat","Maize"], correct:2, explanation:"Wheat is a rabi (winter) crop sown in October–November and harvested in March–April. Cotton, paddy (rice), and maize are primarily kharif crops, though maize and paddy can also be grown in rabi season in some regions." },
  { id:"aeo1_028", year:2017, subject:"agronomy", question:"Integrated Nutrient Management (INM) aims at:", options:["Using only chemical fertilizers","Using only organic manures","Combining organic, inorganic, and biofertilizers for balanced nutrition","Eliminating fertilizers completely"], correct:2, explanation:"Integrated Nutrient Management (INM) involves the combined use of organic manures, inorganic fertilizers, and biofertilizers to maintain soil fertility, reduce input costs, and achieve sustainable crop production." },
  { id:"aeo1_029", year:2017, subject:"agronomy", question:"The recommended N:P:K ratio for general crop production in most Telangana soils is:", options:["4:2:1","1:1:1","2:1:1","3:1:2"], correct:0, explanation:"The general N:P:K recommendation ratio for most crops in Telangana's red and black soils is approximately 4:2:1. However, specific recommendations vary by crop — PJTSAU provides crop-specific recommendations." },
  { id:"aeo1_030", year:2017, subject:"agronomy", question:"Zero tillage saves approximately how much water compared to conventional tillage in wheat?", options:["5–10%","15–20%","25–30%","35–40%"], correct:2, explanation:"Zero tillage (no-till) wheat saves approximately 25–30% water compared to conventionally tilled wheat because the undisturbed soil retains more moisture and the early sowing captures more winter rainfall/dew." },
  { id:"aeo1_031", year:2017, subject:"agronomy", question:"Sugarcane is propagated commercially by:", options:["Seeds","Stem cuttings (setts)","Root cuttings","Grafting"], correct:1, explanation:"Sugarcane is commercially propagated vegetatively using stem cuttings called 'setts' (2–3 budded pieces of stem). Seed propagation is used only in breeding programmes due to poor seed germination and excessive genetic variation." },
  { id:"aeo1_032", year:2017, subject:"agronomy", question:"The term 'Integrated Farming System' (IFS) involves:", options:["Crop production only","Integration of crops, livestock, fishery, and other enterprises on the same farm","Only organic farming methods","Contract farming arrangements"], correct:1, explanation:"Integrated Farming System (IFS) integrates multiple enterprises (crop + livestock + fishery + poultry + horticulture) on the same farm to recycle farm resources, reduce risk, ensure year-round income, and improve resource use efficiency." },
  { id:"aeo1_033", year:2017, subject:"agronomy", question:"Groundnut is a crop of which family?", options:["Solanaceae","Leguminosae (Fabaceae)","Malvaceae","Cucurbitaceae"], correct:1, explanation:"Groundnut (Arachis hypogaea) belongs to family Leguminosae (Fabaceae). It is a leguminous crop that fixes atmospheric nitrogen through Bradyrhizobium root nodules and has geocarpic (underground) pod formation." },
  { id:"aeo1_034", year:2017, subject:"agronomy", question:"The crop duration of short-duration rice varieties is approximately:", options:["60–75 days","90–110 days","120–135 days","150–180 days"], correct:1, explanation:"Short-duration rice varieties (like MTU-1010, DRR Dhan 45) have a crop duration of 90–110 days. Medium duration is 120–130 days and long duration is 135–150+ days. Short-duration varieties allow multiple cropping." },
  { id:"aeo1_035", year:2017, subject:"agronomy", question:"Which micronutrient deficiency is most common in paddy in Telangana?", options:["Iron (Fe)","Manganese (Mn)","Zinc (Zn)","Boron (B)"], correct:2, explanation:"Zinc (Zn) deficiency is the most widespread micronutrient deficiency in paddy across India and Telangana, causing 'Khaira disease' with brown spots and stunting. It is corrected by ZnSO4 application at 25 kg/ha." },
  { id:"aeo1_036", year:2017, subject:"agronomy", question:"The 'System of Rice Intensification' (SRI) was developed in:", options:["Philippines","India","Madagascar","Japan"], correct:2, explanation:"SRI (System of Rice Intensification) was developed in Madagascar by Father Henri de Laulanié in the 1980s. It involves single seedling transplanting, wider spacing, soil aeration (no continuous flooding), and compost application." },
  { id:"aeo1_037", year:2017, subject:"agronomy", question:"Balanced fertilization means applying fertilizers in:", options:["Equal amounts of N, P, K","Quantities matching crop removal and soil supply to meet crop needs","Maximum possible doses","Only organic forms"], correct:1, explanation:"Balanced fertilization means supplying nutrients in quantities that match the difference between crop nutrient demand and soil nutrient supply, based on soil testing and expected yields — avoiding both deficiency and excess." },
  { id:"aeo1_038", year:2017, subject:"agronomy", question:"'Crop rotation' is practiced primarily to:", options:["Reduce soil fertility","Break pest and disease cycles, improve soil health and yield","Increase water use","Reduce seed requirement"], correct:1, explanation:"Crop rotation helps break pest and disease cycles, prevents build-up of specific pests, improves soil structure through diversity of root systems, fixes nitrogen when legumes are included, and reduces weed pressure." },
  { id:"aeo1_039", year:2017, subject:"agronomy", question:"Which irrigation method has the highest water use efficiency (WUE)?", options:["Flood irrigation","Furrow irrigation","Sprinkler irrigation","Drip irrigation"], correct:3, explanation:"Drip (trickle) irrigation has the highest WUE (80–95%) as water is delivered directly to the root zone with minimal evaporation and runoff. Flood irrigation has WUE of only 30–40%, furrow 50–60%, sprinkler 70–80%." },
  { id:"aeo1_040", year:2017, subject:"agronomy", question:"The state of Telangana is primarily characterized by which type of soil?", options:["Alluvial soil","Red and Black (Deep and Shallow) soils","Laterite soil","Saline soil"], correct:1, explanation:"Telangana has predominantly Red soils (in upland areas) and Black (Regur/Vertisols) soils (in Nalgonda, Mahbubnagar, Warangal districts). Red sandy loams cover most of the northern and eastern districts." },

  // ── SOIL SCIENCE & FERTILIZERS (15) ──
  { id:"aeo1_041", year:2017, subject:"soil-science", question:"Optimal soil pH range for most agricultural crops is:", options:["4.0–5.5","5.5–7.5","7.5–9.0","3.0–4.5"], correct:1, explanation:"Most agricultural crops grow best in a soil pH range of 5.5–7.5 (slightly acidic to neutral). This range ensures maximum availability of essential nutrients. Below 5.5 or above 7.5, several nutrients become unavailable." },
  { id:"aeo1_042", year:2017, subject:"soil-science", question:"Gypsum (CaSO4.2H2O) is applied for reclamation of:", options:["Acidic soils","Saline soils","Sodic (alkali) soils","Waterlogged soils"], correct:2, explanation:"Gypsum (CaSO4·2H2O) is the standard amendment for reclaiming sodic (alkali) soils. Calcium displaces the harmful exchangeable sodium (Na+), which is then leached out, reducing ESP and lowering soil pH." },
  { id:"aeo1_043", year:2017, subject:"soil-science", question:"Urea contains what percentage of nitrogen?", options:["21%","26%","36%","46%"], correct:3, explanation:"Urea (CO(NH2)2) contains 46% nitrogen — the highest N content among solid nitrogenous fertilizers. It is the most widely used nitrogen fertilizer in India due to its high analysis and ease of application." },
  { id:"aeo1_044", year:2017, subject:"soil-science", question:"Black soils (Vertisols) of India swell when wet and shrink when dry because they contain:", options:["Kaolinite clay","Montmorillonite (smectite) clay","Illite clay","Halloysite clay"], correct:1, explanation:"Vertisols (black cotton soils) have high montmorillonite (smectite) clay content which has a 2:1 expanding lattice that absorbs water between layers causing swelling, and collapses on drying causing deep cracks (gilgai)." },
  { id:"aeo1_045", year:2017, subject:"soil-science", question:"Nitrogen content in DAP (Di-Ammonium Phosphate) is:", options:["18%","20%","15%","28%"], correct:0, explanation:"DAP (Di-ammonium Phosphate, (NH4)2HPO4) contains 18% N and 46% P2O5. It is the most widely used phosphatic fertilizer in India, providing both N and P in a highly water-soluble form." },
  { id:"aeo1_046", year:2017, subject:"soil-science", question:"Rhizobium inoculant is used as biofertilizer for:", options:["Rice","Leguminous crops","Cotton","Sugarcane"], correct:1, explanation:"Rhizobium forms symbiotic nitrogen-fixing nodules on roots of leguminous crops (groundnut, soybean, chickpea, pigeon pea). Different Rhizobium species are specific to different legume genera. It can fix 50–300 kg N/ha/season." },
  { id:"aeo1_047", year:2017, subject:"soil-science", question:"Soil organic matter (SOM) is important because it:", options:["Increases soil bulk density","Reduces water retention","Improves soil structure, nutrient supply, water retention, and microbial activity","Increases soil pH in acid soils"], correct:2, explanation:"Soil Organic Matter improves soil in multiple ways: binds soil particles into aggregates (improves structure), increases water and nutrient holding capacity, provides nutrients through mineralisation, and supports soil microbial communities." },
  { id:"aeo1_048", year:2017, subject:"soil-science", question:"The process of conversion of ammonia (NH3) to nitrate (NO3-) in soil by bacteria is called:", options:["Denitrification","Nitrification","Ammonification","Nitrogen fixation"], correct:1, explanation:"Nitrification is the two-step oxidation of ammonium (NH4+) to nitrite (NO2-) by Nitrosomonas and then nitrite to nitrate (NO3-) by Nitrobacter. It is an aerobic process that makes N available to plants in nitrate form." },
  { id:"aeo1_049", year:2017, subject:"soil-science", question:"Single Super Phosphate (SSP) contains approximately:", options:["46% P2O5","32% P2O5","26% P2O5","16% P2O5"], correct:3, explanation:"SSP contains approximately 16% P2O5 (water-soluble), along with 12% sulphur (as CaSO4), which benefits oilseed and pulse crops. Despite low P analysis, it is a good sulphur source and is cheaper per tonne." },
  { id:"aeo1_050", year:2017, subject:"soil-science", question:"Which of the following is a secondary macronutrient?", options:["Nitrogen","Phosphorus","Calcium","Iron"], correct:2, explanation:"Secondary macronutrients required by plants in moderate amounts are Calcium (Ca), Magnesium (Mg), and Sulphur (S). Primary macronutrients are N, P, K. Micronutrients include Fe, Zn, Mn, Cu, B, Mo, Cl." },
  { id:"aeo1_051", year:2017, subject:"soil-science", question:"Vermicomposting uses which organism to decompose organic matter?", options:["Bacteria only","Earthworms (Eisenia fetida)","Fungi","Blue-green algae"], correct:1, explanation:"Vermicomposting uses earthworms, primarily Eisenia fetida (red wigglers) or Lumbricus rubellus, to convert organic waste into vermicompost. The process is faster than regular composting and produces a nutrient-rich, pathogen-free product." },
  { id:"aeo1_052", year:2017, subject:"soil-science", question:"Potassium deficiency in plants shows as:", options:["Yellowing of young leaves","Interveinal chlorosis on older leaves","Marginal leaf scorch (burning) of older leaves","Purple/red discolouration of leaves"], correct:2, explanation:"Potassium is mobile in phloem; deficiency appears first on older leaves. Symptoms: scorching (necrosis) of leaf margins and tips starting from older leaves, which is the characteristic 'marginal leaf scorch' of K deficiency." },
  { id:"aeo1_053", year:2017, subject:"soil-science", question:"The Soil Testing Laboratory recommendation is based on:", options:["Farmer's request only","Actual soil nutrient status determined by chemical analysis","Fixed blanket fertilizer recommendations","Neighbouring farmer's practices"], correct:1, explanation:"Soil test-based fertilizer recommendations are made by analysing actual soil nutrient levels (N, P, K, pH, EC, micronutrients) and comparing with critical limits to determine how much additional fertilizer is needed for the target yield." },
  { id:"aeo1_054", year:2017, subject:"soil-science", question:"Green manuring crop Dhaincha (Sesbania aculeata) can fix approximately how much nitrogen?", options:["20–30 kg N/ha","50–100 kg N/ha","200 kg N/ha","5 kg N/ha"], correct:1, explanation:"Sesbania aculeata (Dhaincha) is one of the best green manure crops, fixing approximately 50–100 kg N/ha through root nodules. When incorporated at 45 days, it adds significant organic matter and N to the soil." },
  { id:"aeo1_055", year:2017, subject:"soil-science", question:"Alkaline reaction of sodium carbonate (Na2CO3) in sodic soils makes soil pH rise above:", options:["7.0","8.0","8.5","10.0"], correct:2, explanation:"In sodic soils, the hydrolysis of Na2CO3 produces NaOH, raising soil pH typically above 8.5 (often reaching 9–10). This extreme alkalinity causes precipitation of nutrients (Fe, Mn, Zn) and structural degradation of soil." },

  // ── ENTOMOLOGY & PLANT PATHOLOGY (15) ──
  { id:"aeo1_056", year:2017, subject:"entomology", question:"Integrated Pest Management (IPM) is defined as:", options:["Using only chemical pesticides","Using only biological control","A decision-making approach combining multiple pest control methods to keep pest populations below economic injury levels","Eliminating all pests from the field"], correct:2, explanation:"IPM is an ecosystem-based, decision-making strategy that uses multiple pest management tactics (cultural, biological, chemical, physical) in a compatible way to prevent economic damage while minimising human health and environmental risks." },
  { id:"aeo1_057", year:2017, subject:"entomology", question:"Which pest of cotton is called 'white gold destroyer'?", options:["Jassid","Whitefly","Pink bollworm","Thrips"], correct:2, explanation:"Pink bollworm (Pectinophora gossypiella) is called 'destroyer of white gold' (cotton = white gold). Its larvae bore into bolls and destroy seeds and fibre, causing severe yield loss. Bt cotton was developed primarily against this pest." },
  { id:"aeo1_058", year:2017, subject:"entomology", question:"The 'dead heart' symptom in paddy is caused by:", options:["BPH (Brown Plant Hopper)","Leaf folder","Stem borer","Gall midge"], correct:2, explanation:"Dead heart symptom in paddy (central tiller turning brown and dead at the vegetative stage) is caused by stem borers (Scirpophaga incertulas — yellow stem borer, S. innotata — white stem borer). Gall midge causes 'silver shoot'." },
  { id:"aeo1_059", year:2017, subject:"entomology", question:"Malathion is classified as which type of insecticide?", options:["Organochlorine","Organophosphate","Carbamate","Pyrethroid"], correct:1, explanation:"Malathion is an organophosphate (OP) insecticide that inhibits acetylcholinesterase. It is one of the safest OP insecticides for mammals due to rapid hydrolysis. Used against sucking pests, storage insects, and mosquitoes." },
  { id:"aeo1_060", year:2017, subject:"entomology", question:"Pheromone traps in IPM are primarily used for:", options:["Killing pest populations directly","Monitoring adult insect populations (pest surveillance)","Releasing beneficial insects","Attracting natural enemies"], correct:1, explanation:"Sex pheromone traps are surveillance tools — they attract and trap adult male insects using synthetic sex pheromones. They help monitor pest population density to decide whether and when to apply control measures (ETL-based decisions)." },
  { id:"aeo1_061", year:2017, subject:"plant-pathology", question:"Blast disease of rice is caused by:", options:["Xanthomonas oryzae","Rhizoctonia solani","Magnaporthe oryzae","Helminthosporium oryzae"], correct:2, explanation:"Rice blast caused by Magnaporthe oryzae (ascomycete fungus) is the most destructive rice disease globally, affecting leaves (diamond-shaped lesions), collar, neck (neck rot), and nodes. It thrives in cool, humid conditions." },
  { id:"aeo1_062", year:2017, subject:"plant-pathology", question:"Bordeaux mixture (fungicide) is prepared by mixing:", options:["ZnSO4 + Lime","CuSO4 + Lime","FeSO4 + Lime","MnSO4 + Lime"], correct:1, explanation:"Bordeaux mixture = Copper sulphate (CuSO4·5H2O) + Calcium hydroxide (slaked lime) in a 1:1 ratio in water. It is the oldest and most widely used contact fungicide/bactericide, protecting plants from downy mildew, blights, and cankers." },
  { id:"aeo1_063", year:2017, subject:"plant-pathology", question:"The 'tikka disease' affects which crop?", options:["Wheat","Groundnut","Rice","Maize"], correct:1, explanation:"Tikka disease (early and late leaf spots) of groundnut is caused by Cercospora arachidicola (early leaf spot) and Cercosporidium personatum (late leaf spot). It is one of the most important foliar diseases of groundnut." },
  { id:"aeo1_064", year:2017, subject:"plant-pathology", question:"Wilt disease of tomato is caused by:", options:["Phytophthora infestans","Fusarium oxysporum f.sp. lycopersici","Alternaria solani","Botrytis cinerea"], correct:1, explanation:"Fusarium wilt of tomato is caused by Fusarium oxysporum f.sp. lycopersici (soil-borne vascular pathogen). It causes unilateral leaf wilting, vascular browning, and plant death. Management involves resistant varieties and soil solarisation." },
  { id:"aeo1_065", year:2017, subject:"plant-pathology", question:"Yellow Vein Mosaic (YVM) of Bhendi (okra) is caused by:", options:["A fungus","A begomovirus transmitted by whitefly","A bacteria","A phytoplasma"], correct:1, explanation:"Yellow Vein Mosaic Virus (Bhendi Yellow Vein Mosaic Virus — BYVMV) is a begomovirus (Geminiviridae) transmitted by the whitefly Bemisia tabaci. It causes characteristic yellow vein pattern on leaves and is the most serious virus disease of okra." },
  { id:"aeo1_066", year:2017, subject:"plant-pathology", question:"Downy mildew diseases are caused by fungi of class:", options:["Ascomycetes","Basidiomycetes","Oomycetes (Water moulds)","Zygomycetes"], correct:2, explanation:"Downy mildew diseases are caused by Oomycetes (water moulds) — organisms now placed in Kingdom Chromista rather than true fungi. Major examples: Plasmopara viticola (grape), Sclerospora graminicola (pearl millet), Pseudoperonospora cubensis (cucurbits)." },
  { id:"aeo1_067", year:2017, subject:"plant-pathology", question:"Seed treatment with Thiram (organosulphur fungicide) is used to control:", options:["Soil-borne diseases of seedlings","Foliar diseases during crop growth","Viral diseases","Post-harvest diseases only"], correct:0, explanation:"Thiram (TMTD) is a contact fungicide widely used for seed treatment to control seed-borne and soil-borne fungal pathogens like Pythium (damping-off), Fusarium (root rot), and Aspergillus during germination and early seedling stage." },
  { id:"aeo1_068", year:2017, subject:"entomology", question:"Which insect is the vector of rice tungro virus disease?", options:["Brown planthopper (Nilaparvata lugens)","Green leafhopper (Nephotettix virescens)","Whitefly (Bemisia tabaci)","Thrips (Stenchaetothrips biformis)"], correct:1, explanation:"Rice Tungro Disease (RTD) is caused by Rice Tungro Bacilliform Virus (RTBV) + Rice Tungro Spherical Virus (RTSV), transmitted by the green leafhopper Nephotettix virescens in a semi-persistent manner." },
  { id:"aeo1_069", year:2017, subject:"entomology", question:"Economic Threshold Level (ETL) is defined as:", options:["Zero pest density","The pest density at which control action must be taken to prevent economic damage","The maximum permissible pest density","The pest density causing 50% crop loss"], correct:1, explanation:"ETL is the pest population density at which management action must be initiated (pesticide spraying, biocontrol release) to prevent the pest from reaching the Economic Injury Level (EIL) where economic damage becomes unacceptable." },
  { id:"aeo1_070", year:2017, subject:"entomology", question:"Trichogramma sp. is used as a biological control agent against:", options:["Sucking pests (aphids)","Soil-borne nematodes","Eggs of Lepidopteran pests","Bacterial diseases"], correct:2, explanation:"Trichogramma spp. are egg parasitoids (Hymenoptera: Trichogrammatidae) that parasitise eggs of Lepidoptera (moths and butterflies) like Helicoverpa armigera, Spodoptera litura, and stem borers, preventing larval hatching." },

  // ── HORTICULTURE (10) ──
  { id:"aeo1_071", year:2017, subject:"horticulture", question:"Which mango variety is most popular in Telangana?", options:["Alphonso","Dasheri","Benishan (Banganapalle)","Langra"], correct:2, explanation:"Benishan (also known as Banganapalle) is the most popular mango variety in Telangana and AP, accounting for nearly 70% of the mango area. It has large, yellow, sweet fruits with fibreless flesh. Totapuri and Himayat are also major varieties." },
  { id:"aeo1_072", year:2017, subject:"horticulture", question:"Layering as a method of vegetative propagation is most commonly used in:", options:["Guava","Mango","Rose and Jasmine","Banana"], correct:0, explanation:"Air layering (gootee) is commonly used for guava, litchi, and pomegranate propagation. Ground layering is used for rose and jasmine. Mango is propagated by veneer grafting, banana by suckers." },
  { id:"aeo1_073", year:2017, subject:"horticulture", question:"Tomato belongs to which botanical family?", options:["Cucurbitaceae","Solanaceae","Malvaceae","Leguminosae"], correct:1, explanation:"Tomato (Solanum lycopersicum) belongs to family Solanaceae (nightshade family), along with potato, brinjal, chilli, pepper, and tobacco. Cucurbitaceae includes cucumbers and gourds, Malvaceae includes bhendi and cotton." },
  { id:"aeo1_074", year:2017, subject:"horticulture", question:"The most critical stage for water requirement in banana is:", options:["Planting time","Flowering to bunch development stage","Harvest time","Ratoon stage"], correct:1, explanation:"Banana has highest water requirement during flowering and bunch development (sword leaf emergence to bunch filling). Water stress at this stage causes incomplete bunch formation, reduced finger size, and lower yield." },
  { id:"aeo1_075", year:2017, subject:"horticulture", question:"Mushroom cultivation involves growing fungi on:", options:["Soil only","Prepared substrate (straw, sawdust, grain)","Standing water","Manure only"], correct:1, explanation:"Mushroom cultivation involves growing edible fungi (Agaricus bisporus, Pleurotus ostreatus, Volvariella volvacea) on composted/pasteurised substrates like paddy straw, wheat straw, sawdust, and cotton waste in controlled humidity conditions." },
  { id:"aeo1_076", year:2017, subject:"horticulture", question:"Which vegetable is known as 'poor man's apple' for its nutritional value?", options:["Tomato","Guava","Onion","Brinjal"], correct:1, explanation:"Guava (Psidium guajava) is called 'poor man's apple' because it is nutritionally very rich (high in Vitamin C — 200-300 mg/100g, dietary fibre, calcium) and is available at low cost, making good nutrition accessible to the poor." },
  { id:"aeo1_077", year:2017, subject:"horticulture", question:"National Horticulture Mission (NHM) in India was launched in:", options:["2000–01","2005–06","2010–11","2015–16"], correct:1, explanation:"National Horticulture Mission (NHM) was launched in 2005–06 under the 10th Five Year Plan to promote holistic growth of horticulture sector including area expansion, quality planting material, technology adoption, and post-harvest infrastructure." },
  { id:"aeo1_078", year:2017, subject:"horticulture", question:"Marigold (Tagetes erecta) is primarily grown for:", options:["Edible purposes","Medicinal use only","Flower production and pest repellent","Timber"], correct:2, explanation:"Marigold is grown primarily for cut flowers, loose flowers for garlands/religious use, and as a border plant. It is also used as a trap/companion crop (repels nematodes and some pests) and for lutein/carotenoid extraction." },
  { id:"aeo1_079", year:2017, subject:"horticulture", question:"The process of removing some fruits to improve the size and quality of remaining fruits is:", options:["Thinning","Pinching","Topping","Pruning"], correct:0, explanation:"Fruit thinning involves removing excess fruits (manually, chemically, or mechanically) early in the season to reduce competition among remaining fruits, resulting in larger, better-quality fruits. Used in apple, mango, and citrus." },
  { id:"aeo1_080", year:2017, subject:"horticulture", question:"Which is the largest fruit crop producing state in Telangana?", options:["Warangal","Nalgonda","Karimnagar","Khammam"], correct:1, explanation:"Nalgonda district is the largest contributor to fruit production in Telangana, especially for mango. Districts like Khammam and Bhadradri Kothagudem are also important for banana and mango production." },

  // ── ANIMAL HUSBANDRY (5) ──
  { id:"aeo1_081", year:2017, subject:"animal-husbandry", question:"'Operation Flood' (White Revolution) in India was led by:", options:["Dr. M.S. Swaminathan","Dr. Norman Borlaug","Dr. Verghese Kurien","Dr. R.K. Patil"], correct:2, explanation:"Operation Flood (White Revolution) was implemented by NDDB (National Dairy Development Board) under Dr. Verghese Kurien from 1970–1996. It transformed India from a milk-deficit to the world's largest milk producer." },
  { id:"aeo1_082", year:2017, subject:"animal-husbandry", question:"The Murrah buffalo breed is famous for:", options:["High milk production","Good draught ability","Meat production","Wool production"], correct:0, explanation:"Murrah is the highest milk-producing buffalo breed in the world, originating from Haryana and Punjab. A good Murrah cow can produce 2,000–3,500 litres of milk per lactation with 7–8% fat content." },
  { id:"aeo1_083", year:2017, subject:"animal-husbandry", question:"Foot and Mouth Disease (FMD) in cattle is caused by:", options:["Bacteria","Virus","Fungus","Protozoa"], correct:1, explanation:"FMD (Foot and Mouth Disease) is caused by an Aphthovirus (Picornaviridae). It is a highly contagious disease affecting cloven-hoofed animals (cattle, buffalo, goats, pigs) causing vesicles on feet, mouth, and teats. India has FMD control programme." },
  { id:"aeo1_084", year:2017, subject:"animal-husbandry", question:"The normal lactation period of a cow is approximately:", options:["100 days","200 days","300 days","400 days"], correct:2, explanation:"The normal lactation period (duration of milk production per pregnancy cycle) of a dairy cow is approximately 300–305 days (about 10 months). The dry period (last 2 months before calving) is needed for udder regeneration and calf development." },
  { id:"aeo1_085", year:2017, subject:"animal-husbandry", question:"NABARD was established in:", options:["1975","1979","1982","1990"], correct:2, explanation:"NABARD (National Bank for Agriculture and Rural Development) was established on 12 July 1982 on recommendations of the B. Sivaraman Committee (CRAFICARD), replacing the Agricultural Credit Department of RBI. HQ: Mumbai." },

  // ── GOVERNMENT SCHEMES & POLICIES (10) ──
  { id:"aeo1_086", year:2017, subject:"general-agriculture", question:"The minimum support price (MSP) for agricultural commodities is announced by:", options:["NABARD","State Government Agriculture Departments","Central Government based on CACP recommendations","Food Corporation of India (FCI)"], correct:2, explanation:"MSP is announced by the Central Government (Cabinet Committee on Economic Affairs — CCEA) based on recommendations by the Commission for Agricultural Costs and Prices (CACP), an advisory body under the Ministry of Agriculture." },
  { id:"aeo1_087", year:2017, subject:"general-agriculture", question:"Pradhan Mantri Fasal Bima Yojana (PMFBY) was launched in:", options:["2014","2016","2018","2010"], correct:1, explanation:"PMFBY was launched in February 2016, replacing the National Agricultural Insurance Scheme (NAIS). It provides comprehensive crop insurance at affordable premiums (2% for kharif, 1.5% for rabi, 5% for commercial crops)." },
  { id:"aeo1_088", year:2017, subject:"general-agriculture", question:"The Rythu Bandhu scheme (investment support) was launched by Telangana in:", options:["2018","2019","2016","2020"], correct:0, explanation:"Rythu Bandhu scheme was launched by the Telangana government on 10 May 2018, providing ₹4,000 per acre per season (later revised to ₹5,000/acre/season = ₹10,000/acre/year) as pre-sowing investment support to farmers." },
  { id:"aeo1_089", year:2017, subject:"general-agriculture", question:"National Food Security Mission (NFSM) aims to increase production of:", options:["Milk and eggs","Rice, Wheat, Pulses, and Coarse cereals","Vegetables and fruits","Cotton and jute"], correct:1, explanation:"NFSM (launched 2007-08) aims to increase production of rice, wheat, pulses, and coarse cereals through area expansion, yield improvement, and restoration of soil fertility in targeted districts across major producing states." },
  { id:"aeo1_090", year:2017, subject:"general-agriculture", question:"The 'Paramparagat Krishi Vikas Yojana' (PKVY) promotes:", options:["Chemical intensive farming","Organic farming in clusters","Contract farming","Precision agriculture"], correct:1, explanation:"PKVY (launched 2015) promotes organic farming in 50-acre clusters. Farmers are supported for 3 years for conversion to certified organic farming, soil testing, composting, and organic certification through a cluster approach." },
  { id:"aeo1_091", year:2017, subject:"general-agriculture", question:"'Kisan Call Centre' (KCC) in India provides agricultural advice:", options:["Only to paid subscribers","Free advisory service through toll-free phone line (1800-180-1551)","Through visits to farms only","Through postal service only"], correct:1, explanation:"Kisan Call Centre (KCC) was launched in 2004 by the Ministry of Agriculture. It provides free agricultural advisory services to farmers through a toll-free number (1800-180-1551), operated by trained farm tele-advisors in local languages." },
  { id:"aeo1_092", year:2017, subject:"general-agriculture", question:"National Agricultural Policy 2000 aims for agriculture growth rate of:", options:["2% per year","4% or more per year","6% per year","8% per year"], correct:1, explanation:"The National Agricultural Policy 2000 (India's first standalone agricultural policy) set a target of over 4% growth rate per year in agriculture, with specific focus on bringing private sector, technological upgradation, and infrastructure development." },
  { id:"aeo1_093", year:2017, subject:"general-agriculture", question:"PJTSAU (Prof. Jayashankar Telangana State Agricultural University) was established in:", options:["2010","2012","2014","2016"], correct:2, explanation:"PJTSAU was established in June 2014 after the bifurcation of Andhra Pradesh and formation of Telangana state. It was carved out from ANGRAU (Acharya N.G. Ranga Agricultural University). HQ: Rajendranagar, Hyderabad." },
  { id:"aeo1_094", year:2017, subject:"general-agriculture", question:"The 'Doubling Farmers' Income' (DFI) target set by Government of India was for the year:", options:["2020","2022","2024","2030"], correct:1, explanation:"Prime Minister Modi announced the goal of doubling farmers' income by 2022 in February 2016. A committee under Ashok Dalwai (IDWG — Inter-Ministerial Committee) was constituted to recommend strategies. The target was 2022–23." },
  { id:"aeo1_095", year:2017, subject:"general-agriculture", question:"Which state is the largest producer of rice in India?", options:["Andhra Pradesh","Punjab","West Bengal","Uttar Pradesh"], correct:2, explanation:"West Bengal is consistently the largest producer of rice in India in terms of total production, followed by UP, AP/Telangana, and Punjab. Punjab has the highest productivity (yield per hectare) due to intensive cultivation." },

  // ── RURAL DEVELOPMENT (5) ──
  { id:"aeo1_096", year:2017, subject:"general-agriculture", question:"Panchayati Raj was constitutionally established through which amendment?", options:["42nd Amendment","72nd Amendment","73rd Amendment","86th Amendment"], correct:2, explanation:"The 73rd Constitutional Amendment Act 1992 gave constitutional status to Panchayati Raj Institutions (PRIs). It introduced a three-tier system (Gram Panchayat, Panchayat Samiti/Mandal, Zilla Parishad) with reservations for women and SC/ST." },
  { id:"aeo1_097", year:2017, subject:"general-agriculture", question:"Gram Sabha in Panchayati Raj consists of:", options:["Elected representatives of the gram panchayat","All voters registered in a village panchayat","Government officials of the mandal","Members of SHGs only"], correct:1, explanation:"Gram Sabha consists of ALL registered voters (persons on electoral roll) of the village/gram panchayat area. It is the supreme body of PRIs, meeting at least twice a year to approve plans, budgets, and review development works." },
  { id:"aeo1_098", year:2017, subject:"general-agriculture", question:"PMGSY (Pradhan Mantri Gram Sadak Yojana) is related to:", options:["Rural electrification","Rural road connectivity","Rural drinking water","Rural employment"], correct:1, explanation:"PMGSY (PM Gram Sadak Yojana, launched December 2000) aims to provide all-weather road connectivity to unconnected rural habitations (500+ population in plains, 250+ in hilly/tribal areas). It has connected over 1.8 lakh rural habitations." },
  { id:"aeo1_099", year:2017, subject:"general-agriculture", question:"National Rural Livelihoods Mission (NRLM) aims to:", options:["Provide housing to rural poor","Mobilize rural poor into SHGs and provide credit linkages for sustainable livelihoods","Provide scholarships to rural students","Construct rural health centres"], correct:1, explanation:"NRLM (Aajeevika, launched 2011) mobilises rural poor households into SHGs, provides capacity building, credit linkages through bank loans, skill training, and market access to help them build sustainable livelihoods." },
  { id:"aeo1_100", year:2017, subject:"general-agriculture", question:"As per Agriculture Census 2015-16, what percentage of Indian farmers are small and marginal (< 2 ha)?", options:["50%","68%","86%","95%"], correct:2, explanation:"As per Agriculture Census 2015-16, small and marginal farmers (holding size < 2 hectares) constitute about 86.2% of all operational holdings in India. The average farm size has decreased to 1.08 ha due to fragmentation." },
] as PYQQuestion[];

// ── AEO Model Paper 2 — Based on TGPSC AEO Exam Pattern (Advanced Level) ────
export const AEO_PAPER_2: PYQQuestion[] = [
  // ── EXTENSION EDUCATION (18) ──
  { id:"aeo2_001", year:2019, subject:"extension", question:"The concept of 'diffusion of innovations' was given by:", options:["Kurt Lewin","Everett Rogers","Albert Mayer","J.P. Leagans"], correct:1, explanation:"Everett Rogers published 'Diffusion of Innovations' in 1962, providing a comprehensive theory explaining how new ideas and technologies spread through social systems. He identified five adopter categories and five stages of adoption." },
  { id:"aeo2_002", year:2019, subject:"extension", question:"The full form of FLD in extension activities is:", options:["Farm Level Development","Front Line Demonstration","Farmer Learning Demonstration","Farm Leadership Development"], correct:1, explanation:"FLD (Front Line Demonstration) is conducted by scientists of ICAR/KVK directly on farmers' fields to demonstrate new technology at production potential level. It bridges the yield gap between research farm and farmers' field." },
  { id:"aeo2_003", year:2019, subject:"extension", question:"Which of the following is an individual extension teaching method?", options:["Radio broadcast","Kisan Mela","Result demonstration","Farm and home visit"], correct:3, explanation:"Farm and home visit is an individual contact method where the extension worker visits the farmer's farm and home for advisory services. Mass methods (radio, TV) reach large audiences; result demonstration is a group method." },
  { id:"aeo2_004", year:2019, subject:"extension", question:"The 'IRDP' (Integrated Rural Development Programme) was launched in:", options:["1952","1978","1980","1985"], correct:2, explanation:"IRDP (Integrated Rural Development Programme) was launched in October 1980 across all blocks of India as a self-employment programme for rural poor (BPL families). It was later merged into SGSY (Swarnajayanti Gram Swarozgar Yojana)." },
  { id:"aeo2_005", year:2019, subject:"extension", question:"The number of KVKs in Telangana state is approximately:", options:["11","20","33","50"], correct:2, explanation:"There are 33 KVKs (Krishi Vigyan Kendras) in Telangana, one for each district of the state. KVKs function under SAUs (PJTSAU), ICAR institutes, NGOs, and other organisations as mandated by ICAR." },
  { id:"aeo2_006", year:2019, subject:"extension", question:"'Participatory Rural Appraisal' (PRA) was developed based on:", options:["Government surveys","Traditional extension methods","Rapid Rural Appraisal (RRA) and participatory learning methods","Laboratory research"], correct:2, explanation:"PRA evolved from Rapid Rural Appraisal (RRA) in the late 1980s-early 1990s (Robert Chambers et al.), adding full community participation. PRA uses visual methods (maps, matrices, diagrams) to enable communities to analyse their own situation." },
  { id:"aeo2_007", year:2019, subject:"extension", question:"Which award is given to outstanding farmers for contributions to agriculture?", options:["Padma Bhushan only","Pandit Deen Dayal Upadhyay Krishi Vigyan Protsahan Puraskar","Bharat Ratna","Arjuna Award"], correct:1, explanation:"The Pandit Deen Dayal Upadhyay Krishi Vigyan Protsahan Puraskar (ICAR award) recognises outstanding contributions of farmers and farm women. The Krishi Karman Award recognises states for outstanding food grain production." },
  { id:"aeo2_008", year:2019, subject:"extension", question:"PM-KISAN scheme was launched in:", options:["December 2018","February 2019","April 2019","June 2019"], correct:1, explanation:"PM-KISAN (Pradhan Mantri Kisan Samman Nidhi) was launched by PM Modi on 24 February 2019 from Gorakhpur, UP. The first instalment (₹2,000) was transferred directly to eligible farmers' accounts from December 2018." },
  { id:"aeo2_009", year:2019, subject:"extension", question:"'Kisan Suvidha' mobile app was launched by:", options:["ICAR","Ministry of Agriculture and Farmers' Welfare","NABARD","State governments"], correct:1, explanation:"Kisan Suvidha app was launched by the Ministry of Agriculture and Farmers' Welfare to provide key information to farmers about weather, market prices, agri inputs dealers, plant protection, expert advisory, and government schemes." },
  { id:"aeo2_010", year:2019, subject:"extension", question:"MANAGE (National Institute of Agricultural Extension Management) is located at:", options:["New Delhi","Rajendranagar, Hyderabad","Anand, Gujarat","Pune, Maharashtra"], correct:1, explanation:"MANAGE (National Institute of Agricultural Extension Management) is located at Rajendranagar, Hyderabad. It is an autonomous organisation under the Ministry of Agriculture offering training, research, and consultancy in agricultural extension management." },
  { id:"aeo2_011", year:2019, subject:"extension", question:"The 'Seed Village Programme' aims to:", options:["Establish seed companies in villages","Produce quality seeds at the village level for local distribution","Store seeds in centrally located warehouses","Import seeds from foreign countries"], correct:1, explanation:"Seed Village Programme involves training farmers to produce, certify, and supply quality seeds (foundation/certified) from their own village, reducing dependence on outside sources and ensuring timely availability of quality seeds locally." },
  { id:"aeo2_012", year:2019, subject:"extension", question:"Which government scheme provides price support when market prices fall below MSP?", options:["PM-KISAN","PMFBY","Price Support Scheme (PSS)","RKVY"], correct:2, explanation:"Price Support Scheme (PSS) is implemented by Central Government to protect farmers when market prices of oilseeds, pulses, and commercial crops fall below MSP. NAFED and other designated agencies procure the produce at MSP." },
  { id:"aeo2_013", year:2019, subject:"extension", question:"The 'Village Agricultural Worker' (VAW) in T&V system makes fortnightly visits to:", options:["Research stations","8–10 contact farmers in villages","District headquarters","Block-level offices only"], correct:1, explanation:"In the Training and Visit system, Village Agricultural Worker (Extension Officer) visits 8–10 'contact farmers' in the village on a fixed fortnightly schedule. Contact farmers then spread the technology to neighbouring farmers." },
  { id:"aeo2_014", year:2019, subject:"extension", question:"The concept of 'Leadership' in extension means:", options:["Having authority over others","Ability to influence people to work towards common goals","Holding a government post","Having higher education"], correct:1, explanation:"Leadership in extension education is the ability to influence others to work willingly towards common goals. Extension workers must be good leaders to motivate farmers, build trust, and facilitate group action for agricultural development." },
  { id:"aeo2_015", year:2019, subject:"extension", question:"'Pashu Kisan Credit Card' was introduced to:", options:["Provide loans only for crop production","Provide flexible revolving credit for livestock rearing activities","Provide free insurance for cattle","Issue ration cards to farmers"], correct:1, explanation:"Pashu Kisan Credit Card (Pashu KCC) was introduced to provide short-term working capital credit to livestock farmers for animal husbandry activities (feed, veterinary care, etc.) on revolving credit basis, similar to Kisan Credit Card for crops." },
  { id:"aeo2_016", year:2019, subject:"extension", question:"The main function of Agricultural Extension Officer (AEO) is:", options:["Conducting research experiments","Providing technical guidance and advisory services to farmers at village level","Issuing loans to farmers","Inspecting fertilizer shops"], correct:1, explanation:"The primary function of an AEO is to bridge the gap between agricultural research and farmers by providing technology transfer, technical advice, demonstrations, input supply information, and guidance on government schemes at the village level." },
  { id:"aeo2_017", year:2019, subject:"extension", question:"'Kisan Drones' were introduced in India for:", options:["Aerial photography","Crop monitoring, pest scouting, and precision spraying of pesticides/fertilizers","Weather forecasting","Irrigation management only"], correct:1, explanation:"Kisan drones (agricultural UAVs) are used for crop health monitoring (using multispectral cameras), precision spraying of pesticides and liquid fertilizers (nano-urea, nano-DAP), yield estimation, and land mapping in modern precision agriculture." },
  { id:"aeo2_018", year:2019, subject:"extension", question:"The 10,000 Farmer Producer Organisations (FPOs) programme was launched by Government of India in:", options:["2018","2020","2022","2016"], correct:1, explanation:"The Government of India launched the Formation and Promotion of 10,000 Farmer Producer Organisations (FPOs) scheme in February 2020 with a budget of ₹6,865 crore to be implemented over 5 years, to improve farmer bargaining power and market access." },

  // ── AGRONOMY (18) ──
  { id:"aeo2_019", year:2019, subject:"agronomy", question:"The 'Leaf Area Index' (LAI) is defined as:", options:["Total root area per unit land area","Total leaf area per unit land area","Height of crop canopy","Total biomass per unit area"], correct:1, explanation:"Leaf Area Index (LAI) = Total leaf area of the crop / Ground area. It measures canopy development and light interception. Maximum yield is associated with an LAI of 3–5 for most crops (when nearly 95% light is intercepted)." },
  { id:"aeo2_020", year:2019, subject:"agronomy", question:"The recommended seed rate for direct seeded rice (DSR) is:", options:["10–12 kg/ha","20–25 kg/ha","40–50 kg/ha","60–80 kg/ha"], correct:2, explanation:"For Direct Seeded Rice (DSR), the recommended seed rate is 40–50 kg/ha to establish adequate plant population. For SRI transplanting, only 5–7 kg/ha is needed. For normal transplanting, 25–30 kg/ha for nursery." },
  { id:"aeo2_021", year:2019, subject:"agronomy", question:"'Relay cropping' means:", options:["Growing crops one after another in sequence","Sowing second crop in the standing first crop before harvest","Growing same crop continuously","Mixed cropping without definite rows"], correct:1, explanation:"Relay cropping (relay intercropping) involves sowing the second crop into the standing first crop before the first crop is harvested, often at late grain-filling stage. It ensures timely establishment of the second crop with minimal gap." },
  { id:"aeo2_022", year:2019, subject:"agronomy", question:"The nitrogen fixation by Azolla-Anabaena in paddy fields is approximately:", options:["5–10 kg N/ha/season","20–150 kg N/ha/season","200 kg N/ha/season","1–2 kg N/ha/season"], correct:1, explanation:"Azolla (water fern) with its symbiont Anabaena azollae can fix 20–150 kg N/ha/season under optimal conditions. When grown and incorporated as green manure before transplanting, it significantly reduces chemical nitrogen requirement in paddy." },
  { id:"aeo2_023", year:2019, subject:"agronomy", question:"Which of the following is a deep-rooted crop that can break hardpan?", options:["Rice","Sunflower","Soybean","Wheat"], correct:1, explanation:"Sunflower has a deep taproot system (up to 180 cm) that can penetrate and break compacted layers (hardpan/plough pan) in the soil. It is used in crop rotations to improve subsoil structure and drainage in heavy soils." },
  { id:"aeo2_024", year:2019, subject:"agronomy", question:"The full form of SRI is:", options:["System of Rice Intensification","System of Rice Irrigation","Sustainable Rice Improvement","Scientific Rice Implementation"], correct:0, explanation:"SRI stands for System of Rice Intensification. It is a methodology for increasing rice productivity through changed management of plants, soil, water and nutrients. Key principles: young seedlings, wide spacing, soil aeration, compost use." },
  { id:"aeo2_025", year:2019, subject:"agronomy", question:"Which chemical is used for weed control in rice?", options:["Glyphosate","Butachlor","Atrazine","2,4-D (alone)"], correct:1, explanation:"Butachlor (selective pre-emergence herbicide) is one of the most widely used herbicides for weed control in transplanted rice, controlling annual grasses and some broadleaved weeds. It must be applied 3–5 DAS before weeds emerge." },
  { id:"aeo2_026", year:2019, subject:"agronomy", question:"'Tillage' refers to:", options:["Irrigation of crops","Mechanical manipulation of soil for crop production","Application of fertilizers","Harvesting of crops"], correct:1, explanation:"Tillage is the mechanical manipulation of soil (ploughing, harrowing, puddling) to create a suitable seedbed, incorporate crop residues and manures, control weeds, improve water infiltration, and modify soil structure for root growth." },
  { id:"aeo2_027", year:2019, subject:"agronomy", question:"The 'cropping intensity' is defined as:", options:["Number of crops grown per year","Total cropped area / Net sown area × 100","Number of irrigated crops","Crop density per hectare"], correct:1, explanation:"Cropping intensity = (Total cropped area / Net sown area) × 100%. An intensity of 150% means the same land is cropped 1.5 times per year on average. Telangana's cropping intensity has increased to ~130–140% with assured irrigation." },
  { id:"aeo2_028", year:2019, subject:"agronomy", question:"Which fertilizer is recommended to avoid salt injury to germinating seeds?", options:["Urea placed close to seed","DAP placed with seed","SSP placed below seed","Foliar spray of micronutrients"], correct:2, explanation:"Placement of fertilizer directly with or close to seeds can cause salt injury (osmotic stress) in germinating seeds. SSP (low salt index) placed 5 cm below or to the side of the seed row avoids direct seed contact and salt injury." },
  { id:"aeo2_029", year:2019, subject:"agronomy", question:"Irrigation water quality is primarily determined by:", options:["Water colour and smell","Electrical conductivity (EC), SAR, and pH","Temperature of water","Source of irrigation (canal vs borewell)"], correct:1, explanation:"Irrigation water quality is assessed by Electrical Conductivity (EC — salinity), Sodium Adsorption Ratio (SAR — sodicity hazard), pH, boron content, and residual sodium carbonate (RSC). USSL classification is widely used for quality assessment." },
  { id:"aeo2_030", year:2019, subject:"agronomy", question:"The 'Kalinga-3' variety is associated with which crop?", options:["Wheat","Sorghum","Rice","Cotton"], correct:2, explanation:"Kalinga-3 is a rice variety known for its tolerance to submergence. It was used as a parent in developing SUB1 gene-containing flood-tolerant rice varieties. Traditional rice varieties from Odisha like Kalinga have tolerance traits." },
  { id:"aeo2_031", year:2019, subject:"agronomy", question:"Which crop is known as 'Camel crop' for its drought tolerance?", options:["Bajra (Pearl millet)","Sorghum","Sesame","Castor"], correct:3, explanation:"Castor (Ricinus communis) is called the 'Camel crop' for its exceptional drought tolerance. It has deep roots, can extract moisture from deep soil horizons, has waxy leaves that reduce transpiration, and can withstand dry spells during growth." },
  { id:"aeo2_032", year:2019, subject:"agronomy", question:"'AWD' (Alternate Wetting and Drying) in rice production is used to:", options:["Increase disease resistance","Reduce water use by 15–30% without yield loss","Increase grain size","Eliminate weed management"], correct:1, explanation:"AWD (Alternate Wetting and Drying) is a water-saving irrigation technique for rice where fields are allowed to dry to 15–20 cm below soil surface between irrigations, reducing water use by 15–30% compared to continuous flooding without significant yield loss." },
  { id:"aeo2_033", year:2019, subject:"agronomy", question:"'Rabi' crops are grown in India during:", options:["June to September","October to March","March to June","April to July"], correct:1, explanation:"Rabi (winter) crops are sown from October to November (after kharif harvest) and harvested from February to April. They utilise residual soil moisture, winter rainfall, and cool temperatures. Main rabi crops: wheat, mustard, gram, linseed, potato." },
  { id:"aeo2_034", year:2019, subject:"agronomy", question:"The practice of growing tall and short crops together to maximise use of space and light is called:", options:["Monoculture","Mixed cropping","Strip cropping","Multistorey cropping"], correct:3, explanation:"Multistorey cropping (multi-tier cropping) involves growing plants of different heights simultaneously on the same field to exploit vertical space — tall crops (coconut), medium (banana), short (turmeric), and ground cover (pineapple) in agroforestry." },
  { id:"aeo2_035", year:2019, subject:"agronomy", question:"Boro rice in West Bengal and Assam is grown during:", options:["Kharif season (June–September)","Winter season (November–March)","Summer season (March–June) under irrigation","Year-round"], correct:2, explanation:"Boro rice is grown in the summer (dry) season (December/January to April/May) under irrigation in Eastern India (WB, Assam, Bihar). It has high yield potential (due to clear sunny weather) but requires more water and is grown in low-lying areas." },
  { id:"aeo2_036", year:2019, subject:"agronomy", question:"Which state is the largest producer of cotton in India?", options:["Andhra Pradesh/Telangana","Punjab","Gujarat","Maharashtra"], correct:2, explanation:"Gujarat is the largest producer of cotton in India (about 35–40% of national production), followed by Maharashtra and Telangana/AP. Gujarat has the highest area under cotton with high-yielding Bt cotton varieties dominating." },

  // ── SOIL SCIENCE (12) ──
  { id:"aeo2_037", year:2019, subject:"soil-science", question:"The 'Field Capacity' of soil refers to:", options:["Maximum water soil can hold","Water content held after drainage of excess water (gravitational) has ceased","Minimum water for plant growth","Water available for evaporation only"], correct:1, explanation:"Field Capacity (FC) is the soil moisture content after excess gravitational water has drained away (usually 1–3 days after wetting). It represents the upper limit of plant-available water. Typically held at -0.1 to -0.33 bar (pF 2.0–2.5)." },
  { id:"aeo2_038", year:2019, subject:"soil-science", question:"'Saline soils' have ECe more than:", options:["2 dS/m","4 dS/m","8 dS/m","16 dS/m"], correct:1, explanation:"Saline soils are defined as soils with EC of saturated paste extract (ECe) > 4 dS/m (old unit: mmhos/cm), pH < 8.5, and ESP < 15%. These soils restrict crop growth due to osmotic stress. Reclamation requires leaching with good-quality water." },
  { id:"aeo2_039", year:2019, subject:"soil-science", question:"Phosphorus availability in soil is maximum at pH:", options:["4.0–5.0","5.5–7.0","7.5–8.5","8.5–9.5"], correct:1, explanation:"Phosphorus availability peaks in the pH range 5.5–7.0. Below pH 5.5, P forms insoluble Fe and Al phosphates. Above pH 7.0, P forms calcium phosphates. This is why lime application to acidic soils improves P availability." },
  { id:"aeo2_040", year:2019, subject:"soil-science", question:"Soil horizon 'B' is also called:", options:["Zone of eluviation (leaching)","Zone of illuviation (accumulation)","Parent material zone","Organic litter zone"], correct:1, explanation:"The B horizon (subsoil) is the zone of illuviation (accumulation) where materials leached from the A horizon (clay, organic matter, oxides) accumulate. The A horizon is the zone of eluviation. O is organic litter, C is parent material, R is bedrock." },
  { id:"aeo2_041", year:2019, subject:"soil-science", question:"The 'law of minimum' (Liebig's law) states:", options:["All nutrients are equally important","Crop growth is limited by the nutrient in shortest supply relative to need","Maximum fertilizer gives maximum yield","Organic matter is the most important factor"], correct:1, explanation:"Liebig's Law of Minimum (1840) states that plant growth is controlled not by total resources available but by the scarcest resource (limiting factor). If one essential nutrient is deficient, growth is limited regardless of the abundance of others." },
  { id:"aeo2_042", year:2019, subject:"soil-science", question:"Neem-coated urea (NCU) is beneficial because:", options:["It has higher N content","It releases nitrogen slowly, reduces losses and improves NUE","It contains pesticide properties","It is cheaper than regular urea"], correct:1, explanation:"Neem-coated urea (NCU) has neem oil applied to slow down nitrification (conversion of ammonium to nitrate) — neem's natural nitrification inhibitors reduce N losses by leaching and denitrification, improving N use efficiency by 10–15%." },
  { id:"aeo2_043", year:2019, subject:"soil-science", question:"The major element NOT required by plants in large amounts is:", options:["Nitrogen","Potassium","Manganese","Calcium"], correct:2, explanation:"Manganese (Mn) is a micronutrient — required in very small (trace) amounts (typically 20–500 ppm in plant dry matter). N, P, K, Ca, Mg, S are macronutrients required in larger amounts. Micronutrients: Fe, Zn, Mn, Cu, B, Mo, Cl, Ni." },
  { id:"aeo2_044", year:2019, subject:"soil-science", question:"Sulphur deficiency symptoms in crops include:", options:["Yellowing of older leaves (chlorosis)","Yellowing of young leaves (chlorosis) similar to N deficiency","Marginal leaf scorch","Interveinal chlorosis on old leaves"], correct:1, explanation:"Sulphur deficiency causes uniform yellowing of young (newest) leaves because S is relatively immobile in plants. This distinguishes it from N deficiency (yellowing of old leaves). S deficiency is more common in oilseed and pulse crops." },
  { id:"aeo2_045", year:2019, subject:"soil-science", question:"Soil erosion by water is highest in which type of soil?", options:["Sandy soils","Clay soils","Loamy soils with low organic matter","Soils with high organic matter"], correct:2, explanation:"Loamy soils with low organic matter are most susceptible to water erosion — they have enough fine particles to be dislodged but insufficient aggregation to resist raindrop impact. Soils with >3% organic matter have much better aggregate stability." },
  { id:"aeo2_046", year:2019, subject:"soil-science", question:"KCC (Kisan Credit Card) scheme was launched in:", options:["1990","1995","1998","2002"], correct:2, explanation:"KCC (Kisan Credit Card) scheme was launched in August 1998 based on recommendations of a working group constituted by NABARD (R.V. Gupta Committee). It provides farmers a revolving credit card for crop production and allied activities at reduced interest rates." },
  { id:"aeo2_047", year:2019, subject:"soil-science", question:"Carbon:Nitrogen (C:N) ratio of well decomposed compost is approximately:", options:["100:1","50:1","20:1","5:1"], correct:2, explanation:"Well-matured, decomposed compost has a C:N ratio of approximately 20:1 (sometimes 15:1 to 25:1). Fresh organic matter has a high C:N ratio (>30:1). Soil microbes prefer C:N around 25:1 — above this causes N immobilization." },
  { id:"aeo2_048", year:2019, subject:"soil-science", question:"The Soil Health Card scheme is implemented every how many years?", options:["Every year","Every 2 years","Every 3 years","Every 5 years"], correct:1, explanation:"Soil Health Cards are issued to farmers every 2 years (every two crop seasons) based on soil sample collection and testing from all surveyed plots across India. This allows tracking of soil health changes and updating fertilizer recommendations." },

  // ── PLANT PATHOLOGY & ENTOMOLOGY (12) ──
  { id:"aeo2_049", year:2019, subject:"plant-pathology", question:"'Leaf blight' of rice caused by Helminthosporium oryzae is also known as:", options:["Brown spot disease","Leaf scald","False smut","Narrow brown leaf spot"], correct:0, explanation:"Brown spot disease of rice is caused by Helminthosporium oryzae (Bipolaris oryzae). It caused the Great Bengal Famine (1942-43). Symptoms are oval to circular brown spots with grey or whitish centre on leaves — major during nutrient stress." },
  { id:"aeo2_050", year:2019, subject:"plant-pathology", question:"'Chilli die back' (Phomopsis blight) is caused by:", options:["Phytophthora capsici","Colletotrichum capsici","Fusarium solani","Sclerotinia sclerotiorum"], correct:1, explanation:"Colletotrichum capsici (anthracnose and dieback) is one of the most serious diseases of chilli. It causes dieback of young shoots from tip downward (tip die-back) and post-harvest fruit rot (anthracnose). Major in humid conditions." },
  { id:"aeo2_051", year:2019, subject:"plant-pathology", question:"'Bunchy top' disease of banana is caused by:", options:["A fungus","Banana Bunchy Top Virus (BBTV) transmitted by aphid (Pentalonia nigronervosa)","A bacterium","A phytoplasma transmitted by leafhopper"], correct:1, explanation:"Banana Bunchy Top Virus (BBTV, Nanovirus) is transmitted by the banana aphid Pentalonia nigronervosa. It causes stunted plants with leaves bunched at the top — one of the most destructive banana diseases. No cure; remove and destroy affected plants." },
  { id:"aeo2_052", year:2019, subject:"entomology", question:"The 'leaf hopper' (Amrasca biguttula biguttula) is a serious pest of which crop?", options:["Rice","Cotton","Paddy","Wheat"], correct:1, explanation:"Cotton jassid/leaf hopper (Amrasca biguttula biguttula) is a major sucking pest of cotton. It sucks sap from phloem, causing leaf curling ('hopper burn'). Hairy (resistant) cotton varieties show resistance to jassid attack." },
  { id:"aeo2_053", year:2019, subject:"entomology", question:"Neonicotinoids are a class of systemic insecticides that act on:", options:["Acetylcholinesterase inhibition","Nicotinic acetylcholine receptors","Nerve cell membrane disruption","GABA-gated chloride channels"], correct:1, explanation:"Neonicotinoids (imidacloprid, thiamethoxam, clothianidin) are selective agonists of nicotinic acetylcholine receptors (nAChR) in insect nervous systems, causing continuous nerve stimulation and death. They are highly toxic to bees." },
  { id:"aeo2_054", year:2019, subject:"entomology", question:"Which of the following is a biological pesticide based on a fungus?", options:["Bt (Bacillus thuringiensis)","Beauveria bassiana","Nuclear polyhedrosis virus (NPV)","Trichogramma sp."], correct:1, explanation:"Beauveria bassiana is an entomopathogenic fungus (biological insecticide) that infects and kills insect pests including white grubs, thrips, whiteflies, and termites. The fungal spores germinate and penetrate the insect cuticle." },
  { id:"aeo2_055", year:2019, subject:"entomology", question:"The yellow stem borer (Scirpophaga incertulas) overwinters as:", options:["Egg mass on leaves","Diapausing larva in stem","Adult moth in soil","Pupa in paddy stubble"], correct:1, explanation:"Yellow stem borer (YSB) of rice overwinters (diapauses) as last-instar larvae inside the lower part of paddy stubble and ratoon tillers. These larvae survive the off-season and emerge as moths to infest the next crop." },
  { id:"aeo2_056", year:2019, subject:"entomology", question:"Which of the following insecticide is used for seed treatment against termites?", options:["Chlorpyrifos","Malathion","Carbendazim","Thiram"], correct:0, explanation:"Chlorpyrifos (organophosphate) is widely used as seed treatment, soil drench, and preventive treatment for termite control in agricultural fields. Imidacloprid (neonicotinoid) is also commonly used for seed treatment against termites." },
  { id:"aeo2_057", year:2019, subject:"plant-pathology", question:"'Sheath blight' of rice caused by Rhizoctonia solani can be managed by:", options:["Resistant varieties primarily","Seed treatment with Thiram alone","Spot spray of Hexaconazole or Propiconazole","Deep irrigation"], correct:2, explanation:"Sheath blight management includes: fungicide sprays of triazoles (Hexaconazole, Propiconazole, Tebuconazole) when disease appears, narrower spacing to reduce humidity, and biocontrol with Pseudomonas fluorescens. No highly resistant varieties are available." },
  { id:"aeo2_058", year:2019, subject:"entomology", question:"'Gundhi bug' (Leptocorisa oratorius) damages rice by:", options:["Boring into stem at tillering","Sucking sap from developing grains (milky stage)","Feeding on leaves","Attacking roots"], correct:1, explanation:"Rice gundhi bug (Leptocorisa oratorius, Hemiptera: Alydidae) is a sucking pest that feeds on developing rice grains at the milky stage, leaving characteristic 'chaffy grains' with bad odour. It is more serious in border rows near water channels." },
  { id:"aeo2_059", year:2019, subject:"plant-pathology", question:"Systemic fungicides can:", options:["Only protect plant surfaces from infection","Penetrate plant tissues and cure established infections","Kill all types of fungi equally","Only be used as seed treatments"], correct:1, explanation:"Systemic (curative) fungicides are absorbed and translocated within plant tissues, allowing them to control infections that have already established. Examples: Carbendazim, Propiconazole, Tebuconazole. Contact fungicides (Mancozeb, Copper) only protect surface." },
  { id:"aeo2_060", year:2019, subject:"entomology", question:"Which of the following is the correct economic threshold level (ETL) for leaf folder in rice?", options:["1 moth/light trap/night","2 larvae/tiller or 5% leaf damage","10% leaf damage","5 adults/sq metre"], correct:1, explanation:"For rice leaf folder, ETL is generally 2 larvae per tiller or 5% leaf damage (some references suggest 10% leaf damage for vegetative stage). Management at ETL prevents population from reaching EIL and causing significant yield loss." },

  // ── HORTICULTURE (8) ──
  { id:"aeo2_061", year:2019, subject:"horticulture", question:"The scientific name of chilli is:", options:["Capsicum chinense","Capsicum annuum","Capsicum frutescens","Capsicum baccatum"], correct:1, explanation:"Common chilli (red/green chilli) is Capsicum annuum. Byadagi, Guntur Sannam and most Indian varieties are C. annuum. Pungency is due to capsaicin alkaloids." },
  { id:"aeo2_062", year:2019, subject:"horticulture", question:"'Brix value' in fruits indicates:", options:["Acidity of fruit","Total soluble solids (sugar content) measured by refractometer","Vitamin C content","Water content"], correct:1, explanation:"Brix (°Bx) measures the sugar content (total soluble solids) of the fruit juice using a refractometer. 1°Bx ≈ 1g sucrose per 100g juice. Mango juice: 18–22°Bx; Grapes: 18–24°Bx. Used for harvest maturity and processing." },
  { id:"aeo2_063", year:2019, subject:"horticulture", question:"'Inarching' is a method of vegetative propagation used for:", options:["Banana","Mango","Grapes","Pomegranate"], correct:1, explanation:"Inarching (approach grafting) is used for mango where propagation by cuttings is difficult. Both scion and rootstock plants are grown separately, brought together, and a section of each is joined. Union forms before severing from parent." },
  { id:"aeo2_064", year:2019, subject:"horticulture", question:"Banana is classified botanically as:", options:["A tree","A perennial herb with pseudostem","An annual creeper","A shrub"], correct:1, explanation:"Botanically, banana is not a tree — it is a giant monocotyledonous perennial herb. The 'trunk' is actually a pseudostem formed by tightly packed leaf bases. The true stem is a rhizome (underground corm) from which suckers arise." },
  { id:"aeo2_065", year:2019, subject:"horticulture", question:"Grapes are commercially propagated by:", options:["Seeds","Hardwood stem cuttings","Budding on rootstock","Air layering"], correct:1, explanation:"Grapes are primarily propagated by hardwood stem cuttings (20–30 cm long, pencil-thick) because they root easily. Bench grafting on rootstocks (Dogridge, 1613C) is used for phylloxera-infested or calcareous soils." },
  { id:"aeo2_066", year:2019, subject:"horticulture", question:"National Research Centre for Banana (NRCB) is located at:", options:["Hyderabad","Trichy (Tiruchirappalli), Tamil Nadu","Pune","Bengaluru"], correct:1, explanation:"National Research Centre for Banana (NRCB) — now called ICAR-National Research Centre for Banana — is located at Trichy (Tiruchirappalli), Tamil Nadu. It is the apex research centre for banana in India under ICAR." },
  { id:"aeo2_067", year:2019, subject:"horticulture", question:"The 'Brundaban' variety is associated with which flower crop?", options:["Rose","Marigold","Chrysanthemum","Jasmine"], correct:2, explanation:"Brundaban is a popular chrysanthemum (Chrysanthemum morifolium/Dendranthema grandiflora) variety widely grown in India for loose flowers and garlands. It has yellow flowers and is popular in Telangana and Andhra Pradesh." },
  { id:"aeo2_068", year:2019, subject:"horticulture", question:"'Cauliflower' is the modified part of which plant organ?", options:["Leaf","Compressed stem with modified (hypertrophied) flower buds (curd)","Root","Fruit"], correct:1, explanation:"The 'curd' of cauliflower is a compact mass of undeveloped, hypertrophied, aborted flower buds attached to a compressed stem. It is a modified inflorescence/shoot system — botanically a compressed, branched floral axis." },

  // ── GOVERNMENT & GENERAL (12) ──
  { id:"aeo2_069", year:2019, subject:"general-agriculture", question:"Telangana State was formed on:", options:["2 June 2014","1 November 2014","26 January 2015","15 August 2014"], correct:0, explanation:"Telangana State was officially formed on 2 June 2014 as the 29th state of India, carved out from the existing state of Andhra Pradesh. Hyderabad serves as the joint capital for 10 years." },
  { id:"aeo2_070", year:2019, subject:"general-agriculture", question:"The 'Green Revolution' in India was primarily associated with:", options:["Increase in vegetable production","Introduction of HYV wheat and rice with chemical inputs","Organic farming revolution","Forest conservation"], correct:1, explanation:"Green Revolution (mid-1960s to 1970s) introduced high-yielding semi-dwarf wheat (Norman Borlaug/MS Swaminathan) and rice varieties, combined with chemical fertilizers, pesticides, and irrigation, dramatically increasing food grain production in India." },
  { id:"aeo2_071", year:2019, subject:"general-agriculture", question:"Telangana's 'Mission Kakatiya' was launched for:", options:["Road construction","Restoration and rejuvenation of minor irrigation tanks","Urban development","Forest conservation"], correct:1, explanation:"Mission Kakatiya was launched by Telangana government in 2015 to restore, repair, and revive minor irrigation tanks (Kuntas) across the state. It aims to restore the glory of traditional Kakatiya-era water harvesting infrastructure." },
  { id:"aeo2_072", year:2019, subject:"general-agriculture", question:"Which crop is called 'King of Millets'?", options:["Bajra (Pearl millet)","Jowar (Sorghum)","Finger millet (Ragi)","Foxtail millet (Korralu)"], correct:1, explanation:"Jowar (Sorghum bicolor) is called 'King of Millets' — it is the largest produced millet crop worldwide and is a staple food for millions in dryland areas of Africa and India. It is also called 'Indian Millet' and has high drought tolerance." },
  { id:"aeo2_073", year:2019, subject:"general-agriculture", question:"India's food grain production target in 2022-23 was:", options:["250 million tonnes","300 million tonnes","330 million tonnes","280 million tonnes"], correct:2, explanation:"India's food grain production target for 2022-23 was 330 million tonnes (mtmt) to achieve 'doubling farmers' income' target. Actual production exceeded 323 million tonnes, close to the target. Record production was achieved." },
  { id:"aeo2_074", year:2019, subject:"general-agriculture", question:"Kaleshwaram Lift Irrigation Project (KLIP) in Telangana is built on which river?", options:["Krishna","Godavari","Manjira","Tungabhadra"], correct:1, explanation:"Kaleshwaram Lift Irrigation Scheme (KLIS), the world's largest multi-stage lift irrigation project, lifts water from the Godavari river at Medigadda barrage (Kaleshwaram junction, Jayashankar Bhupalpally). It irrigates 18.25 lakh acres." },
  { id:"aeo2_075", year:2019, subject:"general-agriculture", question:"The 'Father of Indian Green Revolution' is:", options:["Norman Borlaug","Dr. M.S. Swaminathan","C. Subramaniam","B.P. Pal"], correct:1, explanation:"Dr. M.S. Swaminathan is called the 'Father of the Indian Green Revolution'. He introduced semi-dwarf Mexican wheat varieties (Lerma Rojo, Sonora) into India in the 1960s and adapted them to Indian conditions, leading to wheat self-sufficiency." },
  { id:"aeo2_076", year:2019, subject:"general-agriculture", question:"ICAR headquarters is located at:", options:["Mumbai","Hyderabad","New Delhi","Bengaluru"], correct:2, explanation:"ICAR (Indian Council of Agricultural Research) headquarter is at New Delhi (Krishi Bhavan / ICAR Complex, Pusa). It was established in 1929 and is the apex body for coordinating, guiding, and managing agricultural research and education in India." },
  { id:"aeo2_077", year:2019, subject:"general-agriculture", question:"'Crop insurance' in India is currently implemented through:", options:["National Agricultural Insurance Scheme (NAIS)","Pradhan Mantri Fasal Bima Yojana (PMFBY)","National Horticulture Mission","RKVY"], correct:1, explanation:"PMFBY (launched 2016) is the current main crop insurance scheme in India, replacing NAIS and MNAIS. It provides comprehensive insurance coverage for crop failure due to natural calamities, pests, and diseases at subsidized premiums." },
  { id:"aeo2_078", year:2019, subject:"general-agriculture", question:"Which of the following is a carbon credit generating agricultural practice?", options:["Intensive chemical farming","Zero tillage and organic farming (carbon sequestration)","High external input farming","Mono-cropping"], correct:1, explanation:"Zero tillage (no-till) and organic farming sequester carbon in soil by reducing soil disturbance and adding organic matter. Carbon credits are awarded for CO2 equivalent sequestered, providing additional income to farmers under carbon trading schemes." },
  { id:"aeo2_079", year:2019, subject:"general-agriculture", question:"'Geo-tagging' of farmlands helps in:", options:["Irrigation scheduling only","Accurate mapping, identification of beneficiaries and verification of schemes","Weather forecasting","Crop insurance premium calculation only"], correct:1, explanation:"Geo-tagging uses GPS coordinates to map farmlands and infrastructure. It helps in accurate beneficiary identification, scheme verification, preventing fake beneficiaries in DBT schemes, mapping of government assets, and precision agriculture." },
  { id:"aeo2_080", year:2019, subject:"general-agriculture", question:"National Agriculture Market (eNAM) has how many registered mandis approximately?", options:["100 mandis","500 mandis","1,000+ mandis","5,000 mandis"], correct:2, explanation:"As of 2023, e-NAM has integrated over 1,000 APMC markets (mandis) across 23 states and 3 UTs. More than 1.77 crore farmers and 2.6 lakh traders are registered on the platform for online trading of agricultural commodities." },

  // ── RURAL DEVELOPMENT & SCHEMES (10) ──
  { id:"aeo2_081", year:2019, subject:"general-agriculture", question:"PMAY-G (Pradhan Mantri Awaas Yojana — Grameen) aims to:", options:["Provide free food grains","Provide pucca houses to rural poor by 2024","Build roads in rural areas","Provide rural electricity"], correct:1, explanation:"PMAY-G aims to provide all weather pucca houses (with basic amenities — toilet, LPG connection, electricity) to all houseless and kutcha/dilapidated house owners in rural areas. Target: 2.95 crore houses by 2024." },
  { id:"aeo2_082", year:2019, subject:"general-agriculture", question:"National Horticulture Board (NHB) was established in:", options:["1984","1990","2000","2005"], correct:0, explanation:"National Horticulture Board (NHB) was established in 1984 under the Ministry of Agriculture, Government of India, to promote coordinated development of horticulture and provide financial assistance for post-harvest infrastructure." },
  { id:"aeo2_083", year:2019, subject:"general-agriculture", question:"Rajiv Arogyasri scheme is related to:", options:["Agricultural insurance","Health insurance for BPL families (Telangana)","Crop loan interest subsidy","Fertilizer subsidy"], correct:1, explanation:"Rajiv Arogyasri (now Aarogyasri) is a health insurance scheme providing cashless medical treatment up to ₹5 lakh per year to BPL (Below Poverty Line) families in Telangana for 1,044 listed procedures." },
  { id:"aeo2_084", year:2019, subject:"general-agriculture", question:"Which state has the largest area under drip irrigation in India?", options:["Tamil Nadu","Maharashtra","Gujarat","Telangana"], correct:1, explanation:"Maharashtra has the largest area under drip irrigation in India (about 30% of national drip-irrigated area), primarily for sugarcane and grapes. Gujarat and Karnataka also have significant drip areas. Drip is promoted under PM Krishi Sinchai Yojana." },
  { id:"aeo2_085", year:2019, subject:"general-agriculture", question:"'Har Ghar Jal' mission aims to:", options:["Universal rural electrification","Provide piped drinking water to every rural household by 2024","Universal rural sanitation","Rural road connectivity"], correct:1, explanation:"Jal Jeevan Mission (Har Ghar Jal, launched August 2019) aims to provide safe piped drinking water connections to every rural household (19 crore rural households) in India by 2024, improving water quality and reducing water-borne diseases." },
  { id:"aeo2_086", year:2019, subject:"general-agriculture", question:"'Rythu Bima' scheme in Telangana provides:", options:["Crop failure insurance","Life insurance to farmers (₹5 lakh on accidental death)","Cattle insurance","Land development loan"], correct:1, explanation:"Rythu Bima (Group Farmer Life Insurance) scheme by Telangana government provides life insurance of ₹5 lakh to family members of farmers who die accidentally or due to any cause. Premium is fully paid by the State Government." },
  { id:"aeo2_087", year:2019, subject:"general-agriculture", question:"SERP (Society for Elimination of Rural Poverty) in Telangana works primarily with:", options:["Farmers for crop production","Women SHGs for financial inclusion and livelihoods","Government employees","Landless agricultural labourers only"], correct:1, explanation:"SERP (Society for Elimination of Rural Poverty) — now called Mission for Elimination of Poverty in Municipal Areas (MEPMA) for urban, and SERP for rural — implements rural livelihoods through Women SHG federation network in Telangana." },
  { id:"aeo2_088", year:2019, subject:"general-agriculture", question:"Telangana's 'Bangaru Telangana' vision emphasizes:", options:["Industrial development only","Socio-economic development with focus on agriculture, welfare and employment","Tourist development","Export promotion"], correct:1, explanation:"'Bangaru Telangana' (Golden Telangana) is the vision of the Telangana government for comprehensive socio-economic development — covering agricultural welfare (Rythu Bandhu, Rythu Bima), employment (Mission Bhagiratha), and overall prosperity." },
  { id:"aeo2_089", year:2019, subject:"general-agriculture", question:"National Mission for Sustainable Agriculture (NMSA) focuses on:", options:["Export of agricultural products","Enhancing agricultural productivity through climate-resilient practices, water efficiency and soil health","Urban agriculture only","Agricultural marketing infrastructure"], correct:1, explanation:"NMSA (under National Action Plan on Climate Change) promotes climate-smart agriculture through soil health management (SHC), water use efficiency (micro-irrigation), integrated farming systems, and adoption of organic/natural farming practices." },
  { id:"aeo2_090", year:2019, subject:"general-agriculture", question:"'Zero Budget Natural Farming' (ZBNF) is promoted in Telangana through which initiative?", options:["Rythu Bandhu","Green Agriculture Mission","APCNF (Andhra Pradesh and Telangana Natural Farming initiative)","PM-KISAN"], correct:2, explanation:"Zero Budget Natural Farming (ZBNF), pioneered by Subhash Palekar, is being promoted in Andhra Pradesh (APCNF) and Telangana as an alternative to chemical-intensive farming. It uses Bijamrita, Jivamrita, Mulching, and Waaphasa for crops with no external inputs." },

  // ── GENERAL AGRICULTURE (10) ──
  { id:"aeo2_091", year:2019, subject:"general-agriculture", question:"Full form of ICAR is:", options:["Indian Centre for Agriculture Research","Indian Council for Agriculture Research","Indian Council of Agricultural Research","International Council of Agriculture Resources"], correct:2, explanation:"ICAR — Indian Council of Agricultural Research — was established on 16 July 1929 in New Delhi. It is the apex body for planning, conducting, and promoting agricultural research, education, and extension in India." },
  { id:"aeo2_092", year:2019, subject:"general-agriculture", question:"Which crop is known as 'Black Gold' in agriculture?", options:["Cotton","Tobacco","Pepper","Coal"], correct:2, explanation:"Black pepper (Piper nigrum) is known as 'Black Gold' due to its high economic value, trade significance, and dark colour after drying. India (Kerala, Karnataka, Tamil Nadu) is a major black pepper producer. It is the 'king of spices'." },
  { id:"aeo2_093", year:2019, subject:"general-agriculture", question:"The International Rice Research Institute (IRRI) is located in:", options:["India","China","Philippines","Japan"], correct:2, explanation:"IRRI (International Rice Research Institute) is located at Los Baños, Philippines. It was established in 1960 and developed the IR8 'miracle rice' variety that contributed to the Green Revolution in Asia." },
  { id:"aeo2_094", year:2019, subject:"general-agriculture", question:"'Swaminathan Committee' was related to:", options:["Agricultural credit reform","Recommendations for improving farmers' welfare and income (National Commission on Farmers)","Water management","Agricultural export policy"], correct:1, explanation:"National Commission on Farmers (NCF, M.S. Swaminathan Committee, 2004–2006) made comprehensive recommendations for farmer welfare, including C2+50% formula for MSP, land reform, crop insurance, and agricultural debt relief." },
  { id:"aeo2_095", year:2019, subject:"general-agriculture", question:"'Pearl millet' is most commonly known as:", options:["Cholam (Jowar)","Sajje/Bajra","Ragi","Sama"], correct:1, explanation:"Pearl millet is known as Bajra (Hindi), Sajje (Telugu/Kannada), Kambu (Tamil). It is a drought-tolerant, high-temperature-tolerant crop grown in arid/semi-arid areas of Rajasthan, Gujarat, and Haryana. It is nutritionally superior to rice and wheat." },
  { id:"aeo2_096", year:2019, subject:"general-agriculture", question:"'Nano Urea' (liquid) was developed by:", options:["ICAR","IFFCO (Indian Farmers Fertiliser Cooperative)","NRDC","Coromandel International"], correct:1, explanation:"Nano Urea liquid was developed and commercialised by IFFCO (Indian Farmers Fertiliser Cooperative Limited) in 2021. It contains 40,000 ppm nitrogen as nano-particles and is applied as a foliar spray, reducing conventional urea use by 50%." },
  { id:"aeo2_097", year:2019, subject:"general-agriculture", question:"Which state is the leading producer of turmeric in India?", options:["Tamil Nadu","Kerala","Telangana","Maharashtra"], correct:2, explanation:"Telangana (and undivided AP) has been the leading state for turmeric production in India, particularly in Nizamabad district (famous for Nizamabad turmeric). Andhra Pradesh + Telangana together contribute about 50% of national turmeric output." },
  { id:"aeo2_098", year:2019, subject:"general-agriculture", question:"'Agricultural Census' in India is conducted every:", options:["5 years","3 years","10 years","2 years"], correct:0, explanation:"Agricultural Census (census of land holdings) is conducted every 5 years in India under the Ministry of Agriculture. It collects data on number and area of operational holdings by type and size class. Latest is Agriculture Census 2015-16." },
  { id:"aeo2_099", year:2019, subject:"general-agriculture", question:"India's rank in the world in cotton production is:", options:["First","Second","Third","Fifth"], correct:0, explanation:"India is the world's largest producer of cotton (about 23–25% of global production), followed by China and USA. India also has the largest area under cotton cultivation globally. Major producing states: Gujarat, Maharashtra, Telangana, AP, Punjab." },
  { id:"aeo2_100", year:2019, subject:"general-agriculture", question:"Telangana's share in India's total rice production is approximately:", options:["5–7%","10–12%","15–18%","20–25%"], correct:1, explanation:"Telangana contributes approximately 10–12% of India's total rice production, making it one of the top rice-producing states. Kharif paddy is predominantly grown in Karimnagar, Warangal, Khammam, and Nalgonda districts." },
] as PYQQuestion[];
